# 2.7 Scoped IP address rule in nft
stub_nft() {
    cat <<'EOF'
table ip ovn-vpc-nat-gw {
	chain notrack {
		type filter hook prerouting priority -300; policy accept;
		ip saddr 10.0.0.1 notrack
	}
}
EOF
}
if is_stateless_active ""; then
    echo "FAIL: scoped ip saddr nft notrack rule must not be treated as active stateless" >&2
    exit 1
fi

# 2.8 Scoped TCP flags rule in nft
stub_nft() {
    cat <<'EOF'
table ip ovn-vpc-nat-gw {
	chain notrack {
		type filter hook prerouting priority -300; policy accept;
		tcp flags & (fin|syn|rst|ack) == syn notrack
	}
}
EOF
}
if is_stateless_active ""; then
    echo "FAIL: scoped tcp flags nft notrack rule must not be treated as active stateless" >&2
    exit 1
fi

# 3. Test is_stateless_active with iptables
nft_cmd=""
iptables_save_cmd=stub_iptables_save

# 3.1 UDP DNS NOTRACK only
stub_iptables_save() {
    cat <<'EOF'
# Generated by iptables-save
*raw
:PREROUTING ACCEPT [0:0]
-A PREROUTING -p udp -m udp --dport 53 -j NOTRACK
COMMIT
EOF
}
if is_stateless_active ""; then
    echo "FAIL: udp dns NOTRACK must not be treated as active stateless" >&2
    exit 1
fi

# 3.2 Tunnel UDP NOTRACK only
stub_iptables_save() {
    cat <<'EOF'
# Generated by iptables-save
*raw
:PREROUTING ACCEPT [0:0]
